window.__posterData({"id": "kajsa-lilja", "name": "Kajsa Lilja", "folder": "Week1(AI)_Poster_KajsaLilja", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Regler för olika saker.\n// Nya kommentarer på botten\n\nlet myFont; // Låter mig använda mitt typsnitt jag laddat ned.\nlet myCircles = []; // Samlar cirklarna\nlet numberOfCircles = 40; // Antal slumpmässiga cirklar\nlet img; // Stjärnan\nlet showBox = false; // Text inne i stjärna. Om inte klickar dyker den ej upp.\nlet circleImg; // En färdig, suddig cirkel som vi återanvänder\nlet hoverAmount = 0; // 0 = musen är inte över stjärnan, 1 = musen är över (mjuk övergång mellan)\nlet starTurkos; \n\nasync function setup() { \n  myFont = await loadFont('SyneMono-Regular.ttf'); // Mitt typsnitt.\n  createCanvas(600, 800, WEBGL); \n\n  // Vi ritar en suddig cirkel EN gång i en separat bild (createGraphics)\n  circleImg = createGraphics(300, 300);\n  let ctx = circleImg.drawingContext;\n  let grad = ctx.createRadialGradient(150, 150, 0, 150, 150, 150);\n  grad.addColorStop(0, 'rgba(0, 255, 85, 0.4)'); // Grön i mitten\n  grad.addColorStop(1, 'rgba(0, 255, 85, 0)');   // Genomskinlig ytterst\n  ctx.fillStyle = grad;\n  ctx.fillRect(0, 0, 300, 300);\n\n  slumpaCirklar(); // Slumpmässig start på cirklar.\n  img = await loadImage('abstract-star-organic-shape-doodle-graphic-of-modern-element-cute-hand-drawn-playful-scribble-trendy-funky-figure-groovy-simple-naive-art-png.webp'); //Stjärna\n\n  // NYTT: Skapar en turkos \"skugga\" av stjärnan, en gång\n  starTurkos = createGraphics(img.width, img.height);\n  starTurkos.image(img, 0, 0);\n  let sctx = starTurkos.drawingContext;\n  sctx.globalCompositeOperation = 'source-in'; \n  sctx.fillStyle = 'rgb(0, 255, 212)';          // Turkos\n  sctx.fillRect(0, 0, img.width, img.height);\n} \n\nfunction draw() { \n  background(255, 0, 169);// Bakgrundsfärg\n\n  if (!circleImg) return;\n\n  for (let i = 0; i < myCircles.length; i++) {   \n    let c = myCircles[i];\n\n    let pulsStorlek = c.size + sin(frameCount * 0.05 + c.phase) * 30;\n    ritatondadCirkel(c.x, c.y, pulsStorlek); \n  }\n\n  if (img && starTurkos) { \n    let over = musOverStjarna();\n    hoverAmount = lerp(hoverAmount, over ? 1 : 0, 0.1);\n    cursor(over ? HAND : ARROW); \n\n    let skala = lerp(1, 1.15, hoverAmount); \n\n    push();\n      noStroke();\n      translate(200, 250, -50);\n      scale(skala); // Växer när musen är över\n      image(img, -200, -250, 400, 500); // Originalstjärnan\n      translate(0, 0, 1); \n      tint(255, hoverAmount * 255); \n      image(starTurkos, -200, -250, 400, 500); \n    pop();\n  }\n\n  push();\n    translate(-250, 0, 0); \n    textSize(150); \n    fill(213, 0, 255); \n    textFont(myFont); \n    textAlign(LEFT, CENTER); \n    text('R\\nA\\nV\\nE', 0, 0);  // Lägger in \\n för att få texten vertikal istället för horisontal.\n  pop();\n\n  if (showBox === true) { // OM du klickar på stjärna så dyker mitt namn upp. Om du INTE klickar så dyker inte namnet upp. \n    push();\n      translate(150, 210, 100); \n      noStroke();\n      fill(255); \n      textFont(myFont);\n      textSize(18); \n      textAlign(CENTER, CENTER);\n      text(\"Kajsa Lilja\", 0, 0);\n    pop();\n  }\n}\n\nfunction ritatondadCirkel(x, y, storlek) { // Ritar den färdiga suddiga cirkeln i rätt storlek\n  push();\n    translate(x, y, -150);\n    noStroke();\n    image(circleImg, -storlek / 2, -storlek / 2, storlek, storlek); // Ingen loop, bara en bild\n  pop();\n}\n\nfunction slumpaCirklar() { // Cirklarna landar slumpmässigt varje gång man klickar på skärmen\n  myCircles = []; \n  for (let i = 0; i < numberOfCircles; i++) {\n    let circleData = {\n      x: random(-300, 300),\n      y: random(-400, 400),\n      size: random(50, 250),\n      phase: random(0, 6.28) // Varje cirkel får en egen startpunkt i pulsen\n    };\n    myCircles.push(circleData);\n  }\n}\n\nfunction musOverStjarna() {\n  let webglX = mouseX - width/2;\n  let webglY = mouseY - height/2;\n  return webglX > 0 && webglX < 400 && webglY > 0 && webglY < 500;\n}\n\nfunction mousePressed() { // När man klickar med musen. \n  if (musOverStjarna()) {\n    showBox = true;\n  } else {\n    showBox = false;\n  }\n  \n  slumpaCirklar(); // Cirklarna byter plats vid varje klick\n}\n\n//Jag tänkte först att mina cirklar och min stjärna hade varit roliga att leka lite med. Med hjälp av Claude så skrev jag in hela min kod och bad hen först och främst checka så allting var okej (vilket det var) och sedan fråga \"Refactor the code without changing functionality\". Claude att göra cirklarna större och mindre, som att dem andas. Direkt så blev resultatet inte jättebra då min tidigare kod, en for-loop låg i sig själv och stoppade hela processen. Jag fann felet och fixade, tillsammans med att jag tog bort ritatondadCirkel() då den inte behövdes längre. Efter cirklarna så ville jag få stjärnan att agera på något sätt, och då valde jag byte av färg tillsammans med ökad storlek. Claude valde då att använda en variabel för båda dessa förändringar, hoverAmount, och det fungerade super. Jag bytte från standard AI-grön till en turkos färg som skulle matcha min palett enligt htmlcolorcodes.com. ", "assets": {"abstract-star-organic-shape-doodle-graphic-of-modern-element-cute-hand-drawn-playful-scribble-trendy-funky-figure-groovy-simple-naive-art-png.webp": {"mime": "image/webp", "b64": ""}, "SyneMono-Regular.ttf": {"mime": "font/ttf", "b64": ""}}});
